`timescale 1ns/1ps
`default_nettype none
// Sole physical top. radar_system_wrapper is generated by Vivado after the
// supplied integration Tcl, NOT replaced by a hand-written/black-box wrapper.
module radar_m2_top(
    input wire phy_ref_clk_100m_clk_p, input wire phy_ref_clk_100m_clk_n,
    input wire radar_bitclk_p, input wire radar_bitclk_n,
    input wire radar_frclk_p, input wire radar_frclk_n,
    input wire radar_data0_p, input wire radar_data0_n,
    input wire radar_data1_p, input wire radar_data1_n,
    input wire radar_uart_rx, input wire radar_nerr_n, input wire radar_3v3_present,
    output wire radar_uart_tx, output wire radar_nrst_n, output wire radar_sync
);
    wire tx_data, tx_oe, nrst_low, sync_data, sync_oe;
    radar_system_wrapper u_system(
        .phy_ref_clk_100m_clk_p(phy_ref_clk_100m_clk_p),
        .phy_ref_clk_100m_clk_n(phy_ref_clk_100m_clk_n),
        .radar_bitclk_p(radar_bitclk_p),.radar_bitclk_n(radar_bitclk_n),
        .radar_frclk_p(radar_frclk_p),.radar_frclk_n(radar_frclk_n),
        .radar_data0_p(radar_data0_p),.radar_data0_n(radar_data0_n),
        .radar_data1_p(radar_data1_p),.radar_data1_n(radar_data1_n),
        .radar_uart_rx_raw(radar_uart_rx),.radar_nerr_n_raw(radar_nerr_n),
        .radar_3v3_raw(radar_3v3_present),
        .radar_uart_tx_data(tx_data),.radar_uart_tx_oe(tx_oe),
        .radar_nrst_low(nrst_low),.radar_sync_data(sync_data),.radar_sync_oe(sync_oe));
    OBUFT u_uart_tx_obuf(.I(tx_data),.T(!tx_oe),.O(radar_uart_tx));
    OBUFT u_nrst_obuf(.I(1'b0),.T(!nrst_low),.O(radar_nrst_n));
    OBUFT u_sync_obuf(.I(sync_data),.T(!sync_oe),.O(radar_sync));
endmodule
`default_nettype wire
